### Funcionalidade JavaScript
Finalmente, precisamos escrever algumas funções JavaScript para controlar a exibição do modal do carrinho e manipular os eventos dos botões "adicionar ao carrinho":
```javascript
// script.js
let cart = [];
const totalPriceElement = document.getElementById("total-price");

function toggleCart() {
    document.getElementById("cart-modal").style.visibility = 
      document.getElementById("cart-modal").style.visibility === "visible" ? "hidden" : "visible";
}

window.onload = function () {
    const addToCartButtons = document.querySelectorAll(".add-to-cart");

    Array.from(addToCarroButtons).forEach((button) => {
        button.addEventListener("click", handleAddToCartClick);
    });
};

function handleAddToCartClick(event) {
    const productName = event.target.previousElementSibling.textContent.replace(/[\r\n]/g,' ').trim();
    const priceText = event.target.nextElementSibling.innerText;
    const priceNumber = parseFloat(priceText.replace('R$', ''));

    if (!cart.includes(productName)) {
        cart.push({ name: productName, price: priceNumber });
    } else {
        alert(`${productName} já está no seu carrinho.`);
    }

    updateTotalPrice();

    toggleCart(); // Fecha automaticamente após adição
}

function removeItem(name) {
    cart = cart.filter(item => item.name !== name);
    updateTotalPrice();
}

function proceedToPayment() {
    console.log("Redirecionando para pagamento...");
    // Aqui iriamos fazer requisições API ou redirect pra página pagamentos
    location.href = '#'; // Redirecionar temporariamente
}

function closeModal() {
    document.getElementById("cart-modal").style.visibility = "hidden";
}

function updateTotalPrice() {
    let sum = 0;
    for (const item of cart) {
        sum += item.price;
    }
    totalPriceElement.textContent = `R\$ ${sum.toFixed(2)}`;
}
```
